/**
 * Build the browser half into the single self-registering module the Harness
 * module loader expects.
 *
 * The Harness browser module table already seeds `react` and
 * `react/jsx-runtime`, so both stay external and the factory receives them
 * through its `require`. Everything else is bundled. The generated file is
 * committed/published, so installing the package needs no build step.
 *
 * @module scripts/build-client
 */
import { build } from 'esbuild';
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outfile = join(root, 'lib', 'client.js');
const pkg = JSON.parse(await (await import('node:fs/promises')).readFile(join(root, 'package.json'), 'utf8'));

const result = await build({
  absWorkingDir: root,
  entryPoints: ['src/client/index.jsx'],
  bundle: true,
  write: false,
  format: 'cjs',
  platform: 'browser',
  target: ['es2020'],
  jsx: 'automatic',
  external: ['react', 'react/jsx-runtime', 'react-dom', 'react-dom/client'],
  legalComments: 'none',
  define: {
    'process.env.NODE_ENV': '"production"',
  },
  logLevel: 'warning',
});

const code = result.outputFiles[0].text;
const indented = code
  .split('\n')
  .map((line) => (line === '' ? '' : `      ${line}`))
  .join('\n');

const wrapped = `/* Generated by scripts/build-client.mjs — do not edit directly. */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(pkg.name)},
  factory(require) {
    var module = { exports: {} };
    var exports = module.exports;
${indented}
    return module.exports;
  },
});
`;

await mkdir(dirname(outfile), { recursive: true });
await writeFile(outfile, wrapped, 'utf8');
process.stdout.write(`built ${outfile} (${Buffer.byteLength(wrapped)} bytes)\n`);
